from pybricks.hubs import InventorHub
from pybricks.parameters import Button, Direction, Port
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase
from pybricks.tools import StopWatch, multitask, run_task, wait
from umath import floor

from line_sensor_pybricks import LineSensorUR

# Set up.
ls = LineSensorUR('D')
inventor_hub = InventorHub()
left_motor = Motor(Port.F, Direction.COUNTERCLOCKWISE)
right_motor = Motor(Port.E, Direction.CLOCKWISE)
drive_base = DriveBase(left_motor, right_motor, 89, 114)
watch = StopWatch()
data = [0, 0, 0, 0, 0]
data_2 = 0

async def wobble_5s():
    await wait(0)
    watch.reset()
    await drive_base.turn(45)
    while watch.time() <= 5000:
        await wait(0)
        await drive_base.turn(-90)
        await drive_base.turn(90)
        print(watch.time())
    await drive_base.turn(-45)

async def main1():
    while True:
        await wait(0)
        data.append(2 + floor(await ls.position() / 65))
        data.pop(0)
        print(data)
        inventor_hub.display.off()
        for item in range(5):
            await wait(0)
            inventor_hub.display.pixel(item, data[item], 100)
        await wait(300)

async def main2():
    # upload line_sensor_pybricks.py into your pybricks code environment. Get it here:
    # https://github.com/AntonsMindstorms/lms-line-sensor/blob/main/micropython/line_sensor_pybricks.py
    drive_base.settings(turn_rate=100)
    print(await ls.mode_calibrated())
    while True:
        await wait(0)
        if any(inventor_hub.buttons.pressed()):
            await multitask(
                ls.calibrate(),
                wobble_5s(),
            )
        drive_base.drive(80, await ls.position() * 1.5)


async def main():
    await multitask(main1(), main2())

run_task(main())